-- ── 2. ПРОВЕРИТЬ ───────────────────────────────────────────────────────────
--  Ожидаемо: 0 | 0 | 0 | 0.

SELECT count(*) FILTER (WHERE description LIKE '%Заказывайте прямо сейчас%') AS prizyvov,
       count(*) FILTER (WHERE description LIKE '%Срок доставки 1–3 рабочих дня%'
                           OR description LIKE '%по всему Казахстану — в Алматы, Астану%') AS srok_na_ves_kz,
       count(*) FILTER (WHERE description ~ 'В Ухтышке (вы найдёте|представлен|собраны)[^.]*(широк|полн|весь|все линейки)') AS shirokiy_vybor,
       count(*) FILTER (WHERE description LIKE '%бластеры X-Shot%' OR description LIKE '%зимняя коллекция Winter Waves%'
                           OR description LIKE '%мобили и дуги на коляску%' OR description LIKE '%стиральные машины, пылесосы%') AS nesushchestvuyushchee
  FROM public.brands;
